/**
 * The types `node/nrbf/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    RecordType, PrimitiveType, BinaryType, BinaryArrayType
 * depends    —
 * used by    src/node/nrbf/index, src/node/nrbf/reader, src/save-decoder/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

